// The four fixture generators (`scripts/gen-atomic-cases.vl`, `gen-conv-cases.vl`,
// `gen-simd-int-cases.vl`, `gen-shift-mask-fold.vl`) regenerate every committed case they
// own, byte for byte, and the two with `--verify` still agree with the spec table and
// binaryen's decoder.
//
// They were `.py` files until T3 of the architecture refactor. Each port was graded by
// writing its fixtures beside the Python's: identical apart from the `Generated by` line.
// Three behaviours changed on purpose: gen-shift-mask-fold writes the committed file's two
// hand edits (the `@hint` line and the IMIN/IMAX spelling) the Python never learned;
// gen-simd-int-cases' coverage check also reads the float-* cases gen-conv-cases writes,
// where the Python failed on the five rows those cover; and a refusal or statistics line
// goes to stdout, because VL has no stderr sink.
//
// @test-timing native

import { binaryen, COMPILER, exists, nativeEnv, ROOT, VL } from "./support/tree.ts";

const GATED = Deno.env.get("SELFHOST_NATIVE_ALIGN") === "1";
const ENABLED = GATED && exists(VL) && exists(COMPILER);
if (GATED && !ENABLED) {
  console.warn("[vl-gen-cases] skipped — missing vl binary or seed wasm.");
}

const WASM_DIS = binaryen("wasm-dis");
const dec = new TextDecoder();

// Each generator, the arguments it takes beyond `--out`, and the files it writes under it.
// gen-conv-cases runs before gen-simd-int-cases, whose coverage check reads its output.
const GENS: {
  script: string;
  args: (out: string) => string[];
  files: string[];
}[] = [
  {
    script: "gen-atomic-cases",
    args: (out) => ["--out", out],
    files: ["atomics/load-store.vl", "atomics/rmw.vl", "atomics/cmpxchg.vl"],
  },
  {
    script: "gen-conv-cases",
    args: (out) => ["--out", out],
    files: [
      "simd/float-pminmax.vl",
      "simd/float-convert.vl",
      "numerics/trunc-sat.vl",
    ],
  },
  {
    script: "gen-simd-int-cases",
    args: (out) => ["--out", out],
    files: [
      "simd/int-binary.vl",
      "simd/int-unary.vl",
      "simd/int-shift.vl",
      "simd/int-lanes.vl",
    ],
  },
  {
    script: "gen-shift-mask-fold",
    args: (out) => [`${out}/bitwise/shift-mask-fold.vl`],
    files: ["bitwise/shift-mask-fold.vl"],
  },
];

const run = async (script: string, args: string[]) => {
  const { code, stdout } = await new Deno.Command(VL, {
    args: ["run", `scripts/${script}.vl`, "--", ...args],
    cwd: ROOT,
    stdout: "piped",
    stderr: "piped",
    env: nativeEnv({ NO_COLOR: "1", VL }),
  }).output();
  return { code, out: dec.decode(stdout) };
};

Deno.test({
  name: "fixture generators: every committed case regenerates byte for byte",
  ignore: !ENABLED,
  fn: async () => {
    const dir = await Deno.makeTempDir({ prefix: "vl_gen_cases_" });
    try {
      for (const sub of ["atomics", "simd", "numerics", "bitwise"]) {
        await Deno.mkdir(`${dir}/${sub}`);
      }
      const bad: string[] = [];
      for (const g of GENS) {
        const { code, out } = await run(g.script, g.args(dir));
        if (code !== 0) {
          bad.push(`[${g.script}] want exit 0, got exit ${code}:\n${out}`);
          continue;
        }
        for (const f of g.files) {
          const want = await Deno.readTextFile(`${ROOT}/tests/cases/${f}`);
          const got = await Deno.readTextFile(`${dir}/${f}`);
          if (got !== want) {
            bad.push(
              `[${g.script}] ${f} differs from the committed case; want ${want.length} chars, got ${got.length}`,
            );
          }
        }
      }
      if (bad.length > 0) throw new Error(bad.join("\n\n"));
    } finally {
      await Deno.remove(dir, { recursive: true });
    }
  },
});

Deno.test({
  name: "fixture generators: --verify agrees with the spec table and wasm-dis",
  ignore: !ENABLED || !exists(WASM_DIS),
  fn: async () => {
    const dir = await Deno.makeTempDir({ prefix: "vl_gen_cases_verify_" });
    try {
      for (const sub of ["atomics", "simd", "numerics"]) {
        await Deno.mkdir(`${dir}/${sub}`);
      }
      const want: Record<string, string> = {
        "gen-atomic-cases":
          "opcodes: 67 emitted, equal to the spec table's 67; wasm-dis: 67 decoded, 0 disagree",
        "gen-conv-cases":
          "opcodes: 16 emitted, equal to the spec table's 16; wasm-dis: 16 decoded, 0 disagree",
      };
      const bad: string[] = [];
      for (const [script, line] of Object.entries(want)) {
        const { code, out } = await run(script, ["--out", dir, "--verify"]);
        if (code !== 0 || !out.split("\n").includes(line)) {
          bad.push(
            `[${script}] want exit 0 and:\n${line}\ngot exit ${code}:\n${out}`,
          );
        }
      }
      if (bad.length > 0) throw new Error(bad.join("\n\n"));
    } finally {
      await Deno.remove(dir, { recursive: true });
    }
  },
});
